import pandas as pd
import numpy as np
from joblib import Parallel, delayed

def calculate_total_annotations(data):
    return data['annotation'].notna().sum()

def calculate_max_time_s(data):
    return data['time_s'].max()

def estimate_average_heart_rate(df, record_id):
    record_df = df[df['record_id'] == record_id]

    if record_df.empty:
        raise ValueError(f"No data found for record_id {record_id}")

    results = Parallel(n_jobs=-1)(delayed(func)(record_df) for func in [calculate_total_annotations, calculate_max_time_s])

    total_annotations = results[0]
    max_time_s = results[1]

    if total_annotations == 0 or max_time_s == 0:
        raise ValueError(f"Invalid data for record_id {record_id}: no annotations or zero duration")

    estimated_heart_rate = (total_annotations / max_time_s) * 60

    return estimated_heart_rate

def main():
    record_id = 208
    estimated_heart_rate = estimate_average_heart_rate(df, record_id)
    result = estimated_heart_rate

import pandas as pd
import numpy as np
from scipy.stats import pearsonr

def calculate_max_mlii_amplitude(df):
    max_mlii_amplitudes = {}
    for record_id in df['record_id'].unique():
        record_df = df[df['record_id'] == record_id]
        max_mlii_amplitude = np.max(np.abs(record_df['MLII']))
        max_mlii_amplitudes[record_id] = max_mlii_amplitude
    return max_mlii_amplitudes

def calculate_bmi(weight, height):
    return weight / (height ** 2)

def calculate_correlation(max_mlii_amplitudes, bmi_values):
    max_mlii_amplitude_list = []
    bmi_list = []
    for record_id in max_mlii_amplitudes:
        if record_id in bmi_values:
            max_mlii_amplitude_list.append(max_mlii_amplitudes[record_id])
            bmi_list.append(bmi_values[record_id])
    correlation_coefficient, _ = pearsonr(max_mlii_amplitude_list, bmi_list)
    return correlation_coefficient

